    @mcp.custom_route(
        "/api/calliope/realtime-transcription", methods=["POST"]
    )
    async def create_calliope_realtime_transcription(request):
        owner, err = api_owner(request)
        if err:
            return err
        if not config.realtime_transcription_enabled:
            return json_response({
                "error": {
                    "code": "REALTIME_TRANSCRIPTION_UNAVAILABLE",
                    "message": "Live transcription is not configured for this installation.",
                }
            }, 503)
        try:
            content_length = int(request.headers.get("content-length") or 0)
        except (TypeError, ValueError):
            content_length = 0
        if content_length > _MAX_REALTIME_SDP_BYTES + 32 * 1024:
            return json_response({
                "error": {
                    "code": "REALTIME_OFFER_TOO_LARGE",
                    "message": "That live-transcription connection offer is too large.",
                }
            }, 413)
        content_type = str(request.headers.get("content-type") or "").lower()
        surface = "chat"
        session_id = None
        try:
            if content_type.startswith("multipart/form-data"):
                form = await request.form()
                sdp_value = form.get("sdp")
                surface = str(form.get("surface") or "chat").strip().lower()
                session_id = form.get("session_id")
                if callable(getattr(sdp_value, "read", None)):
                    sdp_value = await sdp_value.read(_MAX_REALTIME_SDP_BYTES + 1)
                if isinstance(sdp_value, bytes):
                    sdp = sdp_value.decode("utf-8", "strict")
                else:
                    sdp = str(sdp_value or "")
            elif content_type.startswith(("application/sdp", "text/plain")):
                payload = await request.body()
                if len(payload) > _MAX_REALTIME_SDP_BYTES:
                    raise OverflowError
                sdp = payload.decode("utf-8", "strict")
                surface = str(
                    request.query_params.get("surface") or "chat"
                ).strip().lower()
                session_id = request.query_params.get("session_id")
            else:
                return json_response({
                    "error": {
                        "code": "BAD_REALTIME_OFFER",
                        "message": "Calliope could not read that live-transcription connection offer.",
                    }
                }, 415)
        except OverflowError:
            return json_response({
                "error": {
                    "code": "REALTIME_OFFER_TOO_LARGE",
                    "message": "That live-transcription connection offer is too large.",
                }
            }, 413)
        except (UnicodeDecodeError, ValueError):
            return json_response({
                "error": {
                    "code": "BAD_REALTIME_OFFER",
                    "message": "Calliope could not read that live-transcription connection offer.",
                }
            }, 400)
        except Exception:
            return json_response({
                "error": {
                    "code": "BAD_REALTIME_OFFER",
                    "message": "Calliope could not read that live-transcription connection offer.",
                }
            }, 400)
        if surface not in {"chat", "daily_note"}:
            return json_response({
                "error": {
                    "code": "BAD_TRANSCRIPTION_SURFACE",
                    "message": "That speech destination is not supported.",
                }
            }, 400)
        if len(sdp.encode("utf-8")) > _MAX_REALTIME_SDP_BYTES:
            return json_response({
                "error": {
                    "code": "REALTIME_OFFER_TOO_LARGE",
                    "message": "That live-transcription connection offer is too large.",
                }
            }, 413)
        if (
            not sdp.startswith("v=0")
            or "m=audio" not in sdp
            or "m=video" in sdp
            or "\x00" in sdp
        ):
            return json_response({
                "error": {
                    "code": "BAD_REALTIME_OFFER",
                    "message": "That live-transcription connection offer is invalid.",
                }
            }, 400)
        keywords = await asyncio.to_thread(
            _transcription_context_keywords,
            conn_factory,
            config,
            owner,
            session_id,
        )
        try:
            answer = await _create_realtime_transcription_call(
                config,
                sdp,
                owner=owner,
                surface=surface,
                keywords=keywords,
            )
        except TranscriptionProviderError as exc:
            status = 503 if exc.code in {
                "REALTIME_TRANSCRIPTION_UNAVAILABLE",
                "REALTIME_PROVIDER_UNAVAILABLE",
                "TRANSCRIPTION_RATE_LIMITED",
            } else 502
            return json_response({
                "error": {"code": exc.code, "message": str(exc)[:400]}
            }, status)
        return Response(
            answer,
            media_type="application/sdp",
            headers={
                "cache-control": "no-store",
                "x-content-type-options": "nosniff",
            },
        )

    @mcp.custom_route("/api/calliope/transcriptions", methods=["POST"])
    async def create_calliope_transcription(request):
        _, err = api_owner(request)
        if err:
            return err
        if not config.transcription_enabled:
            return json_response({
                "error": {
                    "code": "TRANSCRIPTION_UNAVAILABLE",
                    "message": "Speech transcription is not configured for this installation.",
                }
            }, 503)
        try:
            content_length = int(request.headers.get("content-length") or 0)
        except (TypeError, ValueError):
            content_length = 0
        if content_length > config.max_audio_bytes + 128 * 1024:
            return json_response({
                "error": {
                    "code": "AUDIO_TOO_LARGE",
                    "message": "That recording is larger than this installation allows.",
                }
            }, 413)
        try:
            form = await request.form()
        except Exception:
            return json_response({
                "error": {
                    "code": "BAD_AUDIO_UPLOAD",
                    "message": "Calliope could not read that recording.",
                }
            }, 400)
        upload = form.get("file")
        surface = str(form.get("surface") or "chat").strip().lower()
        if surface not in {"chat", "daily_note"}:
            try:
                await upload.close()
            except Exception:
                pass
            return json_response({
                "error": {
                    "code": "BAD_TRANSCRIPTION_SURFACE",
                    "message": "That speech destination is not supported.",
                }
            }, 400)
        if upload is None or not callable(getattr(upload, "read", None)):
            return json_response({
                "error": {
                    "code": "AUDIO_REQUIRED",
                    "message": "Record some speech before asking Calliope to transcribe it.",
                }
            }, 400)
        try:
            payload = await upload.read(config.max_audio_bytes + 1)
        except Exception:
            return json_response({
                "error": {
                    "code": "BAD_AUDIO_UPLOAD",
                    "message": "Calliope could not read that recording.",
                }
            }, 400)
        finally:
            try:
                await upload.close()
            except Exception:
                pass
        if len(payload) > config.max_audio_bytes:
            return json_response({
                "error": {
                    "code": "AUDIO_TOO_LARGE",
                    "message": "That recording is larger than this installation allows.",
                }
            }, 413)
        if len(payload) < 32:
            return json_response({
                "error": {
                    "code": "EMPTY_AUDIO",
                    "message": "That recording was too short to transcribe.",
                }
            }, 400)
        detected = _transcription_audio_format(payload)
        if not detected:
            return json_response({
                "error": {
                    "code": "UNSUPPORTED_AUDIO",
                    "message": "Use a browser recording in WebM, MP4/M4A, WAV, or MP3 format.",
                }
            }, 415)
        extension, media_type = detected
        try:
            result = await _transcribe_audio(
                config,
                payload,
                extension=extension,
                media_type=media_type,
                surface=surface,
            )
        except TranscriptionProviderError as exc:
            status = 503 if exc.code in {
                "TRANSCRIPTION_UNAVAILABLE",
                "TRANSCRIPTION_PROVIDER_UNAVAILABLE",
                "TRANSCRIPTION_RATE_LIMITED",
            } else 502
            return json_response({
                "error": {"code": exc.code, "message": str(exc)[:400]}
            }, status)
        return json_response({**result, "retained_audio": False})

    @mcp.custom_route("/api/calliope/voice/renders", methods=["POST"])
    async def create_calliope_voice_render(request):
        owner, err = api_owner(request)
        if err:
            return err
        if not config.voice_enabled:
            return json_response({
                "error": {
                    "code": "VOICE_UNAVAILABLE",
                    "message": "Spoken responses are not configured for this installation.",
                }
            }, 503)
        try:
            content_length = int(request.headers.get("content-length") or 0)
        except (TypeError, ValueError):
            content_length = 0
        if content_length > 32 * 1024:
            return json_response({
                "error": {
                    "code": "VOICE_REQUEST_TOO_LARGE",
                    "message": "That voice preference is too large.",
                }
            }, 413)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        try:
            render, reused = await asyncio.wait_for(
                asyncio.to_thread(
                    _voice_render,
                    conn_factory,
                    config,
                    owner,
                    body.get("session_id"),
                    body.get("turn_id"),
                    body.get("mode"),
                    body.get("personality"),
                ),
                timeout=config.voice_prepare_timeout_seconds,
            )
        except TimeoutError:
            print(
                "WARNING: Calliope conversational voice rewrite timed out",
                file=os.sys.stderr,
            )
            return json_response({
                "error": {
                    "code": "VOICE_TEXT_TIMEOUT",
                    "stage": "text",
                    "message": (
                        "The conversational rewrite took too long. "
                        "Showing the complete answer instead."
                    ),
                }
            }, 504)
        except LookupError as exc:
            return json_response({
                "error": {"code": "VOICE_TURN_NOT_FOUND", "message": str(exc)}
            }, 404)
        except ValueError as exc:
            return json_response({
                "error": {"code": "VOICE_REQUEST_INVALID", "message": str(exc)}
            }, 400)
        except Exception as exc:
            print(f"WARNING: Calliope voice render failed: {exc}", file=os.sys.stderr)
            return json_response({
                "error": {
                    "code": "VOICE_RENDER_FAILED",
                    "stage": "text",
                    "message": "Calliope could not prepare that spoken response.",
                }
            }, 502)
        render_id = quote(str(render["id"]), safe="")
        turn_id = quote(str(body.get("turn_id") or ""), safe="")
        return json_response({
            "render": render,
            "reused": reused,
            "audio_url": f"/api/calliope/voice/turns/{turn_id}/audio?render={render_id}",
        }, 200 if reused else 201)

    @mcp.custom_route(
        "/api/calliope/voice/turns/{turn_id}/audio", methods=["GET"]
    )
    async def stream_calliope_voice_audio(request):
        owner, err = api_owner(request)
        if err:
            return err
        if not config.voice_enabled:
            return json_response({
                "error": {
                    "code": "VOICE_UNAVAILABLE",
                    "message": "Spoken responses are not configured for this installation.",
                }
            }, 503)
        try:
            render = await asyncio.wait_for(
                asyncio.to_thread(
                    _voice_render_for_audio,
                    conn_factory,
                    owner,
                    request.path_params.get("turn_id"),
                    request.query_params.get("render"),
                    config.voice_prepare_timeout_seconds,
                ),
                timeout=config.voice_prepare_timeout_seconds,
            )
        except TimeoutError:
            return json_response({
                "error": {
                    "code": "VOICE_AUDIO_TIMEOUT",
                    "stage": "audio",
                    "message": "Audio generation did not start in time.",
                }
            }, 504)
        except LookupError as exc:
            return json_response({
                "error": {"code": "VOICE_RENDER_NOT_FOUND", "message": str(exc)}
            }, 404)

        cache_path = _voice_cache_path(config, render)
        timing_path = _voice_timing_cache_path(cache_path)
        try:
            cache_size = cache_path.stat().st_size
        except OSError:
            cache_size = 0
        cached_frames = (
            _read_voice_timing_cache(
                timing_path,
                audio_size=cache_size,
                sample_rate=config.voice_sample_rate,
            )
            if 0 < cache_size <= config.max_voice_audio_bytes and cache_size % 2 == 0
            else None
        )
        audio_headers = {
            "cache-control": "private, max-age=86400",
            "x-content-type-options": "nosniff",
            "x-audio-format": "s16le",
            "x-audio-sample-rate": str(config.voice_sample_rate),
            "x-calliope-voice-mode": str(render.get("mode") or "fast"),
            "x-calliope-audio-protocol": _VOICE_STREAM_PROTOCOL,
        }

        if cached_frames:
            async def cached_audio_stream() -> AsyncIterator[bytes]:
                with cache_path.open("rb") as handle:
                    for frame in cached_frames:
                        audio = handle.read(frame["byte_length"])
                        if len(audio) != frame["byte_length"]:
                            yield _voice_stream_error(
                                "The cached spoken response was incomplete.",
                                "VOICE_CACHE_INVALID",
                            )
                            return
                        yield _voice_stream_line(
                            audio,
                            audio_offset_seconds=frame["audio_offset_seconds"],
                            alignment=frame.get("alignment"),
                        )

            return StreamingResponse(
                cached_audio_stream(),
                media_type="application/x-ndjson",
                headers=audio_headers,
            )

        try:
            client, upstream = await asyncio.wait_for(
                _open_voice_provider_stream(config, render),
                timeout=config.voice_prepare_timeout_seconds,
            )
        except TimeoutError:
            print(
                "WARNING: Calliope voice provider connection timed out",
                file=os.sys.stderr,
            )
            return json_response({
                "error": {
                    "code": "VOICE_AUDIO_TIMEOUT",
                    "stage": "audio",
                    "message": "Audio generation did not start in time.",
                }
            }, 504)
        except VoiceProviderError as exc:
            status = 503 if exc.code in {
                "VOICE_UNAVAILABLE",
                "VOICE_PROVIDER_UNAVAILABLE",
                "VOICE_RATE_LIMITED",
            } else 502
            return json_response({
                "error": {
                    "code": exc.code,
                    "stage": "audio",
                    "message": str(exc)[:400],
                }
            }, status)

        cache_path.parent.mkdir(parents=True, exist_ok=True)
        temporary = cache_path.with_name(
            f".{cache_path.name}.{uuid.uuid4().hex}.part"
        )
        timing_temporary = timing_path.with_name(
            f".{timing_path.name}.{uuid.uuid4().hex}.part"
        )

        async def audio_stream() -> AsyncIterator[bytes]:
            written = 0
            complete = False
            frames: list[dict[str, Any]] = []
            first_audio_deadline = (
                time.monotonic() + config.voice_prepare_timeout_seconds
            )
            try:
                with temporary.open("wb") as handle:
                    provider_lines = upstream.aiter_lines().__aiter__()
                    while True:
                        try:
                            if written:
                                line = await anext(provider_lines)
                            else:
                                remaining = first_audio_deadline - time.monotonic()
                                if remaining <= 0:
                                    raise TimeoutError
                                line = await asyncio.wait_for(
                                    anext(provider_lines),
                                    timeout=remaining,
                                )
                        except StopAsyncIteration:
                            break
                        audio, alignment = _voice_provider_frame(line)
                        if not audio:
                            continue
                        if len(audio) % 2:
                            raise VoiceProviderError(
                                "The voice provider returned malformed PCM audio.",
                                "VOICE_PROVIDER_STREAM_INVALID",
                            )
                        offset = written / (config.voice_sample_rate * 2)
                        written += len(audio)
                        if written > config.max_voice_audio_bytes:
                            raise VoiceProviderError(
                                "The generated spoken response was unexpectedly large.",
                                "VOICE_AUDIO_TOO_LARGE",
                            )
                        handle.write(audio)
                        frames.append({
                            "byte_length": len(audio),
                            "audio_offset_seconds": round(offset, 6),
                            "alignment": alignment,
                        })
                        yield _voice_stream_line(
                            audio,
                            audio_offset_seconds=offset,
                            alignment=alignment,
                        )
                complete = written > 0 and written % 2 == 0
                if not complete:
                    yield _voice_stream_error(
                        "The voice provider returned no playable audio.",
                        "VOICE_PROVIDER_STREAM_EMPTY",
                    )
            except VoiceProviderError as exc:
                request_id = str(
                    upstream.headers.get("request-id")
                    or upstream.headers.get("x-request-id")
                    or ""
                )[:160]
                print(
                    "WARNING: ElevenLabs voice stream failed: "
                    f"code={exc.code} request_id={request_id or '-'} detail={exc}",
                    file=os.sys.stderr,
                )
                yield _voice_stream_error(str(exc), exc.code)
            except TimeoutError:
                print(
                    "WARNING: Calliope voice provider produced no audio before timeout",
                    file=os.sys.stderr,
                )
                yield _voice_stream_error(
                    "Audio generation did not start in time.",
                    "VOICE_AUDIO_TIMEOUT",
                )
            finally:
                await upstream.aclose()
                await client.aclose()
                if complete:
                    timing_temporary.write_text(
                        json.dumps(
                            {
                                "protocol": _VOICE_STREAM_PROTOCOL,
                                "sample_rate": config.voice_sample_rate,
                                "frames": frames,
                            },
                            separators=(",", ":"),
                        ),
                        encoding="utf-8",
                    )
                    os.replace(temporary, cache_path)
                    os.replace(timing_temporary, timing_path)
                else:
                    temporary.unlink(missing_ok=True)
                    timing_temporary.unlink(missing_ok=True)

        return StreamingResponse(
            audio_stream(),
            media_type="application/x-ndjson",
            headers=audio_headers,
        )

    @mcp.custom_route("/api/calliope/inventory", methods=["GET"])
    async def list_calliope_inventory(request):
        owner, err = api_owner(request)
        if err:
            return err
        query = str(request.query_params.get("q") or "")[:600]
        section = request.query_params.get("section")
        state = request.query_params.get("state")
        try:
            limit = max(
                1,
                min(
                    int(request.query_params.get("limit") or _MAX_LIBRARY_INVENTORY_RESULTS),
                    _MAX_LIBRARY_INVENTORY_RESULTS,
                ),
            )
            snapshot = await asyncio.to_thread(
                _library_inventory_snapshot,
                conn_factory,
                owner,
                query=query,
                section=section,
                state=state,
                limit=limit,
            )
        except ValueError as exc:
            return json_response(
                {"error": {"code": "BAD_INVENTORY_QUERY", "message": str(exc)}}, 400
            )
        return json_response(snapshot)

    def team_json(value: Any, success_status: int = 200) -> Response:
        payload = dict(value) if isinstance(value, dict) else {
            "error": {"code": "TEAM_SERVICE_ERROR", "message": "The Team service returned an invalid response."}
        }
        status = int(payload.pop("_http_status", success_status))
        if payload.get("error") and status < 400:
            status = 400
        return json_response(payload, status)

    @mcp.custom_route("/api/calliope/teams", methods=["GET"])
    async def list_calliope_teams(request):
        owner, err = api_owner(request)
        if err:
            return err
        if not team_service:
            return json_response({
                "error": {"code": "TEAMS_UNAVAILABLE", "message": "Teams are not available on this installation."}
            }, 503)
        query = str(request.query_params.get("q") or "")[:240]
        signed_session = auth.read_session_full(request) or {}
        display_name = str(signed_session.get("name") or "")[:160] or None
        try:
            teams, people = await asyncio.gather(
                asyncio.to_thread(team_service["list"], owner, query, True, 500),
                asyncio.to_thread(
                    team_service["people"], owner, query, 500, display_name
                ),
            )
        except Exception as exc:
            return json_response({
                "error": {"code": "TEAM_SERVICE_ERROR", "message": str(exc)[:600]}
            }, 500)
        if teams.get("error"):
            return team_json(teams)
        if people.get("error"):
            return team_json(people)
        return json_response({
            "subject": teams.get("subject") or people.get("subject"),
            "can_manage": bool(teams.get("can_manage") and people.get("can_manage")),
            "teams": teams.get("teams") or [],
            "people": people.get("people") or [],
        })

