    @mcp.custom_route(
        "/api/calliope/styles/{profile_id}/fork",
        methods=["POST"],
    )
    async def fork_design_profile(request):
        owner, err = api_owner(request)
        if err:
            return err
        source = _design_profile_json(
            conn_factory,
            request.path_params["profile_id"],
            owner,
            include_versions=True,
        )
        if not source or not source.get("version"):
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        requested_version = _uuid(body.get("version_id"))
        if body.get("version_id") not in (None, "") and not requested_version:
            return json_response({"error": {"code": "INVALID_STYLE_VERSION"}}, 400)
        versions = source.get("versions") or [source["version"]]
        version = (
            next(
                (item for item in versions if item["id"] == requested_version),
                None,
            )
            if requested_version
            else source["version"]
        )
        if not version:
            return json_response({"error": {"code": "STYLE_VERSION_NOT_FOUND"}}, 404)
        name = _clean_design_profile_name(
            body.get("name") or f"{source['name']} copy"
        )
        generated = {
            "name": name,
            "description": source.get("description") or "",
            "source_summary": (
                f"Forked from {source['name']} version {version['version']}. "
                + str(version.get("source_summary") or "")
            )[:4_000],
            "markdown": version["markdown"],
            "tokens": version.get("tokens") or {},
        }
        references = _design_profile_references(
            conn_factory,
            config,
            version["id"],
        )
        try:
            profile = _persist_new_design_profile(
                conn_factory,
                config,
                owner,
                generated,
                references,
            )
        except Exception as exc:
            if "duplicate key" in str(exc).lower():
                return json_response(
                    {
                        "error": {
                            "code": "STYLE_NAME_EXISTS",
                            "message": "Choose a different name for the copy",
                        }
                    },
                    409,
                )
            raise
        return json_response({"profile": profile}, 201)

    @mcp.custom_route("/api/calliope/style-assets/{asset_id}", methods=["GET"])
    async def get_design_profile_asset(request):
        _, err = api_owner(request)
        if err:
            return err
        aid = _uuid(request.path_params["asset_id"])
        if not aid:
            return Response(status_code=404)
        with conn_factory() as conn:
            row = conn.execute(
                "SELECT a.* FROM rvbbit.calliope_design_profile_assets a "
                "JOIN rvbbit.calliope_design_profile_versions v "
                "ON v.id=a.profile_version_id "
                "JOIN rvbbit.calliope_design_profiles p ON p.id=v.profile_id "
                "WHERE a.id=%s::uuid",
                (aid,),
            ).fetchone()
        if not row or not row.get("storage_path") or not row.get("mime_type"):
            return Response(status_code=404)
        try:
            path = Path(str(row["storage_path"])).resolve(strict=True)
            path.relative_to((config.file_root / "styles").resolve())
        except (OSError, RuntimeError, ValueError):
            return Response(status_code=404)
        if not path.is_file():
            return Response(status_code=404)
        return FileResponse(
            path,
            media_type=str(row["mime_type"]),
            filename=row.get("original_name") or path.name,
            content_disposition_type="inline",
            headers={
                "cache-control": "private, no-store",
                "x-content-type-options": "nosniff",
            },
        )

    @mcp.custom_route("/api/calliope/cubes/{cube}/pivot", methods=["POST"])
    async def calliope_cube_pivot(request):
        owner, err = api_owner(request)
        if err:
            return err
        if cube_pivot is None:
            return json_response(
                {
                    "error": {
                        "code": "CUBE_PIVOT_UNAVAILABLE",
                        "message": "direct cube pivots are not configured",
                    }
                },
                503,
            )
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        session = auth.read_session_full(request) or {}
        result = cube_pivot(
            request.path_params["cube"],
            body.get("rows"),
            body.get("cols"),
            body.get("measure"),
            body.get("aggregate") or "sum",
            body.get("measures"),
            session.get("sub"),
            owner,
        )
        error = result.get("error") if isinstance(result, dict) else None
        if not error:
            return json_response(result)
        code = str(error.get("code") or "")
        status = 404 if code == "CUBE_NOT_FOUND" else 400
        if code in {"CUBE_PIVOT_FAILED", "EXCEPTION"}:
            status = 500
        return json_response(result, status)

    def decode_evidence_request(value: Any) -> tuple[str, int, Response | None]:
        body = value if isinstance(value, dict) else {}
        query = re.sub(r"\s+", " ", str(body.get("query") or "")).strip()
        if len(query) < 2:
            return "", 24, json_response(
                {
                    "error": {
                        "code": "QUERY_TOO_SHORT",
                        "message": "Describe what you want to find in at least two characters.",
                    }
                },
                400,
            )
        if len(query) > _MAX_EVIDENCE_QUERY_CHARS:
            return "", 24, json_response({"error": {"code": "QUERY_TOO_LONG"}}, 400)
        try:
            limit = max(6, min(int(body.get("limit") or 24), _MAX_EVIDENCE_RESULTS))
        except (TypeError, ValueError):
            limit = 24
        return query, limit, None

    async def resolve_evidence_bundle(query: str, owner: str, limit: int) -> dict[str, Any]:
        if evidence_search is None:
            raise RuntimeError("The company evidence resolver is not configured.")
        raw_result = await asyncio.to_thread(evidence_search, query, owner, limit)
        if inspect.isawaitable(raw_result):
            raw_result = await raw_result
        return _normalize_evidence_search_result(raw_result, query)

    def persist_evidence_bundle(
        session: dict[str, Any],
        owner: str,
        query: str,
        result: dict[str, Any],
        *,
        origin: str,
        turn_kind: str = "evidence_search",
        surface_title: str | None = None,
        tool_name: str = "evidence_search",
        lineage_key: str | None = None,
    ) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
        clean_turn_kind = re.sub(r"[^a-z0-9_-]", "_", str(turn_kind).lower())[:60]
        clean_tool_name = re.sub(r"[^a-zA-Z0-9_.:-]", "_", str(tool_name))[:120]
        clean_lineage = str(lineage_key or "").strip()[:500]
        if not clean_lineage:
            search_key = hashlib.sha256(query.lower().encode("utf-8")).hexdigest()[:24]
            clean_lineage = f"evidence-search:{search_key}"
        turn_id = str(uuid.uuid4())
        with conn_factory() as conn:
            with conn.transaction():
                locked = conn.execute(
                    "SELECT * FROM rvbbit.calliope_sessions "
                    "WHERE id=%s::uuid AND owner_email=%s FOR UPDATE",
                    (str(session["id"]), owner),
                ).fetchone()
                if not locked:
                    raise LookupError("Calliope session not found")
                next_ordinal = conn.execute(
                    "SELECT coalesce(max(ordinal),0)+1 AS n FROM rvbbit.calliope_turns "
                    "WHERE session_id=%s::uuid",
                    (str(session["id"]),),
                ).fetchone()["n"]
                turn = conn.execute(
                    "INSERT INTO rvbbit.calliope_turns "
                    "(id,session_id,ordinal,user_message,assistant_message,status,completed_at,turn_kind) "
                    "VALUES (%s::uuid,%s::uuid,%s,%s,NULL,'complete',now(),%s) "
                    "RETURNING *",
                    (turn_id, str(session["id"]), next_ordinal, query, clean_turn_kind),
                ).fetchone()
                session = conn.execute(
                    "UPDATE rvbbit.calliope_sessions SET updated_at=now() "
                    "WHERE id=%s::uuid RETURNING *",
                    (str(session["id"]),),
                ).fetchone()
        try:
            surfaces = _insert_surfaces(
                conn_factory,
                str(session["id"]),
                turn_id,
                [{
                    "kind": "evidence",
                    "title": str(surface_title or f"Evidence · {query}")[:240],
                    "tool_name": clean_tool_name,
                    "tool_call_id": f"{clean_tool_name}:{uuid.uuid4()}",
                    "lineage_key": clean_lineage,
                    "payload": result,
                    "source": {
                        "origin": origin,
                        "query": query,
                        "searched": result.get("searched") or [],
                    },
                }],
            )
            if not surfaces:
                raise RuntimeError("The evidence was resolved but could not be saved.")
        except Exception:
            with conn_factory() as conn:
                conn.execute(
                    "DELETE FROM rvbbit.calliope_turns WHERE id=%s::uuid",
                    (turn_id,),
                )
            raise
        return dict(session), dict(turn), surfaces[0]

    async def discard_created_session(session: dict[str, Any]) -> None:
        with conn_factory() as conn:
            conn.execute(
                "DELETE FROM rvbbit.calliope_sessions WHERE id=%s::uuid",
                (str(session["id"]),),
            )
        try:
            await _hermes_json(
                config,
                "DELETE",
                f"/api/sessions/{quote(str(session['hermes_session_id']), safe='')}",
            )
        except Exception:
            pass

    def brief_status_row(owner: str, timezone_name: str, zone: ZoneInfo) -> dict[str, Any]:
        local_date = datetime.now(timezone.utc).astimezone(zone).date()
        with conn_factory() as conn:
            row = conn.execute(
                "SELECT b.*,s.archived,s.title FROM rvbbit.calliope_briefs b "
                "JOIN rvbbit.calliope_sessions s ON s.id=b.session_id "
                "WHERE lower(b.owner_email)=lower(%s) AND b.brief_date=%s",
                (owner, local_date),
            ).fetchone()
        if not row:
            return {
                "available": True,
                "exists": False,
                "date": str(local_date),
                "timezone": timezone_name,
                "item_count": 0,
                "source_count": 0,
            }
        return {
            "available": True,
            "exists": True,
            "id": str(row["id"]),
            "date": str(row["brief_date"]),
            "timezone": str(row.get("timezone") or timezone_name),
            "session_id": str(row["session_id"]),
            "surface_id": str(row["latest_surface_id"]) if row.get("latest_surface_id") else None,
            "item_count": int(row.get("item_count") or 0),
            "source_count": int(row.get("source_count") or 0),
            "refreshed_at": _now_iso(row.get("refreshed_at")) if row.get("refreshed_at") else None,
            "archived": bool(row.get("archived")),
        }

    async def get_or_create_daily_brief(
        owner: str,
        timezone_name: str,
        zone: ZoneInfo,
    ) -> tuple[dict[str, Any], bool]:
        now = datetime.now(timezone.utc)
        local_now = now.astimezone(zone)
        brief_date = local_now.date()
        with conn_factory() as conn:
            row = conn.execute(
                "SELECT b.*,s.hermes_session_id,s.title,s.archived,s.updated_at "
                "FROM rvbbit.calliope_briefs b "
                "JOIN rvbbit.calliope_sessions s ON s.id=b.session_id "
                "WHERE lower(b.owner_email)=lower(%s) AND b.brief_date=%s",
                (owner, brief_date),
            ).fetchone()
            if row:
                if row.get("archived"):
                    conn.execute(
                        "UPDATE rvbbit.calliope_sessions SET archived=false,updated_at=now() "
                        "WHERE id=%s::uuid",
                        (str(row["session_id"]),),
                    )
                    row = {**dict(row), "archived": False}
                return dict(row), False
            previous = conn.execute(
                "SELECT refreshed_at,created_at FROM rvbbit.calliope_briefs "
                "WHERE lower(owner_email)=lower(%s) AND brief_date<%s "
                "ORDER BY brief_date DESC LIMIT 1",
                (owner, brief_date),
            ).fetchone()

        previous_at = _brief_parse_datetime(
            (previous or {}).get("refreshed_at") or (previous or {}).get("created_at"),
            zone,
        )
        window_start = previous_at or now - timedelta(days=_BRIEF_DEFAULT_PAST_DAYS)
        # A future horizon is intentionally anchored to the viewer's local day,
        # so calendar-like sources resolve the same set throughout that day.
        future_date = brief_date + timedelta(days=_BRIEF_DEFAULT_FUTURE_DAYS + 1)
        window_end = datetime.combine(future_date, datetime_time.min, tzinfo=zone).astimezone(timezone.utc)
        title = f"Brief · {brief_date.strftime('%B')} {brief_date.day}"
        created_session = await _create_session_record(
            config,
            conn_factory,
            owner,
            title,
        )
        brief_id = str(uuid.uuid4())
        try:
            with conn_factory() as conn:
                row = conn.execute(
                    "INSERT INTO rvbbit.calliope_briefs "
                    "(id,owner_email,brief_date,timezone,session_id,window_start,window_end) "
                    "VALUES (%s::uuid,%s,%s,%s,%s::uuid,%s,%s) RETURNING *",
                    (
                        brief_id,
                        owner,
                        brief_date,
                        timezone_name,
                        str(created_session["id"]),
                        window_start,
                        window_end,
                    ),
                ).fetchone()
        except Exception as exc:
            # A second browser tab may have won the unique owner/day race.
            await discard_created_session(created_session)
            with conn_factory() as conn:
                row = conn.execute(
                    "SELECT b.*,s.hermes_session_id,s.title,s.archived,s.updated_at "
                    "FROM rvbbit.calliope_briefs b "
                    "JOIN rvbbit.calliope_sessions s ON s.id=b.session_id "
                    "WHERE lower(b.owner_email)=lower(%s) AND b.brief_date=%s",
                    (owner, brief_date),
                ).fetchone()
            if not row:
                raise exc
            return dict(row), False
        return {**dict(row), **{
            "hermes_session_id": created_session["hermes_session_id"],
            "title": created_session["title"],
            "archived": False,
            "updated_at": created_session["updated_at"],
        }}, True

    def stored_brief_bundle(
        owner: str,
        brief: dict[str, Any],
    ) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]] | None:
        surface_id = _uuid(brief.get("latest_surface_id"))
        if not surface_id:
            return None
        with conn_factory() as conn:
            row = conn.execute(
                "SELECT s.*,t.id AS turn_exists FROM rvbbit.calliope_surfaces s "
                "JOIN rvbbit.calliope_turns t ON t.id=s.turn_id "
                "JOIN rvbbit.calliope_sessions n ON n.id=s.session_id "
                "WHERE s.id=%s::uuid AND n.owner_email=%s AND n.id=%s::uuid",
                (surface_id, owner, str(brief["session_id"])),
            ).fetchone()
            if not row:
                return None
            turn = conn.execute(
                "SELECT * FROM rvbbit.calliope_turns WHERE id=%s::uuid",
                (str(row["turn_id"]),),
            ).fetchone()
            session = conn.execute(
                "SELECT * FROM rvbbit.calliope_sessions WHERE id=%s::uuid",
                (str(brief["session_id"]),),
            ).fetchone()
        if not turn or not session:
            return None
        return dict(session), dict(turn), _surface_json(row)

    async def resolve_daily_brief(
        owner: str,
        timezone_name: str,
        zone: ZoneInfo,
        *,
        refresh: bool,
    ) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any], bool, bool]:
        brief, created = await get_or_create_daily_brief(owner, timezone_name, zone)
        if not refresh:
            stored = stored_brief_bundle(owner, brief)
            if stored:
                return *stored, created, False
        if google_calendar_enabled:
            try:
                await _sync_google_calendar(conn_factory, owner)
            except LookupError:
                pass
            except Exception:
                # The resolver will preserve the cached rows and expose a
                # source warning; a Calendar outage must not erase the rest of
                # a user's Brief.
                pass
        raw = await asyncio.to_thread(
            _personal_brief_snapshot,
            conn_factory,
            owner,
            brief,
            include_google_calendar=google_calendar_enabled,
        )
        result = _normalize_personal_brief_result(raw)
        label = f"Brief · {brief['brief_date']}"
        session = _session_for_owner(conn_factory, str(brief["session_id"]), owner)
        if not session:
            raise LookupError("The Personal Brief session is no longer available")
        session, turn, surface = persist_evidence_bundle(
            session,
            owner,
            label,
            result,
            origin="calliope_personal_brief_resolver",
            turn_kind="brief",
            surface_title=label,
            tool_name="personal_brief",
            lineage_key=f"personal-brief:{brief['brief_date']}",
        )
        brief_meta = result.get("brief") or {}
        with conn_factory() as conn:
            conn.execute(
                "UPDATE rvbbit.calliope_briefs SET latest_surface_id=%s::uuid,"
                "item_count=%s,source_count=%s,refreshed_at=now() WHERE id=%s::uuid",
                (
                    str(surface["id"]),
                    int(result.get("count") or 0),
                    int(brief_meta.get("source_count") or 0),
                    str(brief["id"]),
                ),
            )
        return session, turn, surface, created, True

    @mcp.custom_route("/api/calliope/briefs/status", methods=["GET"])
    async def personal_brief_status(request):
        owner, err = api_owner(request)
        if err:
            return err
        try:
            timezone_name, zone = _brief_timezone(request.query_params.get("timezone"))
        except ValueError as exc:
            return json_response(
                {"error": {"code": "INVALID_TIMEZONE", "message": str(exc)}},
                400,
            )
        payload = {"brief": brief_status_row(owner, timezone_name, zone)}
        if google_calendar_enabled:
            payload["calendar"] = await asyncio.to_thread(
                _google_calendar_status, conn_factory, owner
            )
        return json_response(payload)

    @mcp.custom_route("/api/calliope/briefs/today", methods=["POST"])
    async def personal_brief_today(request):
        owner, err = api_owner(request)
        if err:
            return err
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        try:
            timezone_name, zone = _brief_timezone(body.get("timezone"))
            session, turn, surface, created, refreshed = await resolve_daily_brief(
                owner,
                timezone_name,
                zone,
                refresh=bool(body.get("refresh")),
            )
        except ValueError as exc:
            return json_response(
                {"error": {"code": "INVALID_BRIEF", "message": str(exc)}},
                400,
            )
        except LookupError as exc:
            return json_response(
                {"error": {"code": "BRIEF_NOT_FOUND", "message": str(exc)}},
                404,
            )
        except Exception as exc:
            return json_response(
                {"error": {"code": "BRIEF_RESOLVE_FAILED", "message": str(exc)[:600]}},
                502,
            )
        url = "/calliope?" + urlencode({
            "session": str(session["id"]),
            "surface": str(surface["id"]),
        })
        return json_response({
            "mode": "personal_brief",
            "created_session": created,
            "refreshed": refreshed,
            "session": _session_json(session),
            "turn": _turn_json(turn),
            "surface": surface,
            "url": url,
        }, 201 if refreshed else 200)

