    @mcp.custom_route("/api/calliope/sessions/{session_id}", methods=["GET"])
    async def get_session(request):
        owner, err = api_owner(request)
        if err:
            return err
        try:
            with conn_factory() as conn:
                session = calliope_access.require_view(
                    conn, request.path_params["session_id"], owner
                )
                audience = calliope_access._audience(conn, session)
        except calliope_access.CalliopeAccessError as exc:
            return access_error_response(exc)
        if session.get("access_role") == "owner":
            _reconcile_session_files(conn_factory, config, str(session["id"]))
        with conn_factory() as conn:
            turns = conn.execute(
                "SELECT t.*,p.display_name AS author_profile_name,"
                "p.avatar_key::text AS author_avatar_key "
                "FROM rvbbit.calliope_turns t "
                "LEFT JOIN rvbbit.application_principals p "
                "ON p.email=lower(t.author_email) WHERE t.session_id=%s::uuid "
                "ORDER BY ordinal",
                (str(session["id"]),),
            ).fetchall()
            surfaces = conn.execute(
                "SELECT * FROM rvbbit.calliope_surfaces WHERE session_id=%s::uuid "
                "ORDER BY created_at DESC, ordinal DESC",
                (str(session["id"]),),
            ).fetchall()
            try:
                with conn.transaction():
                    playbook_sources = conn.execute(
                        "SELECT v.source_turn_id::text,p.id::text AS playbook_id,v.version,v.title,"
                        "(p.approved_version=v.version) AS approved "
                        "FROM rvbbit.calliope_playbook_versions v "
                        "JOIN rvbbit.calliope_playbooks p ON p.id=v.playbook_id "
                        "WHERE v.source_session_id=%s::uuid AND v.source_turn_id IS NOT NULL "
                        "AND lower(p.owner_email)=lower(%s) ORDER BY v.created_at DESC LIMIT 200",
                        (str(session["id"]), owner),
                    ).fetchall() if session.get("access_role") == "owner" else []
            except Exception:
                playbook_sources = []
        playbook_surface_cache: dict[
            tuple[str, int | None], dict[str, Any] | None
        ] = {}
        visible_surfaces = [
            projected
            for row in surfaces
            if (
                projected := _playbook_surface_json(
                    conn_factory,
                    owner,
                    row,
                    playbook_surface_cache,
                )
            )
            is not None
        ]
        saved_by_turn: dict[str, list[dict[str, Any]]] = {}
        for row in playbook_sources:
            saved_by_turn.setdefault(str(row["source_turn_id"]), []).append({
                "id": str(row["playbook_id"]),
                "version": int(row["version"]),
                "title": str(row.get("title") or "Playbook")[:240],
                "approved": bool(row.get("approved")),
            })
        turn_items = []
        for row in turns:
            turn = _turn_json(row)
            saved = saved_by_turn.get(str(turn.get("id") or ""), [])
            if saved:
                turn["response_receipt"] = {
                    **(turn.get("response_receipt") or {}),
                    "saved_playbooks": saved,
                }
            turn_items.append(turn)
        return json_response({
            "session": _session_json(session),
            "turns": turn_items,
            "surfaces": visible_surfaces,
            "audience": audience,
        })

    @mcp.custom_route("/api/calliope/sessions/{session_id}", methods=["PATCH"])
    async def patch_session(request):
        owner, err = api_owner(request)
        if err:
            return err
        session = _session_for_owner(conn_factory, request.path_params["session_id"], owner)
        if not session:
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        try:
            body = await request.json()
        except Exception:
            body = {}
        updates, values = [], []
        if "title" in body:
            title = re.sub(r"\s+", " ", str(body.get("title") or "")).strip()[:120]
            if not title:
                return json_response({"error": {"code": "INVALID_TITLE"}}, 400)
            updates.append("title=%s")
            values.append(title)
            updates.append("title_source='manual'")
            updates.append("title_generated_at=NULL")
        if "archived" in body:
            updates.append("archived=%s")
            values.append(bool(body.get("archived")))
        if "design_profile_version_id" in body:
            requested = body.get("design_profile_version_id")
            version_id = _uuid(requested)
            if requested not in (None, "") and not version_id:
                return json_response(
                    {"error": {"code": "INVALID_DESIGN_PROFILE"}},
                    400,
                )
            if version_id and not _design_profile_version(
                conn_factory,
                version_id,
                active_only=True,
            ):
                return json_response(
                    {"error": {"code": "DESIGN_PROFILE_NOT_FOUND"}},
                    404,
                )
            updates.append("design_profile_version_id=%s::uuid")
            values.append(version_id)
        if not updates:
            return json_response({"error": {"code": "NO_CHANGES"}}, 400)
        values.extend([str(session["id"]), owner])
        with conn_factory() as conn:
            row = conn.execute(
                f"UPDATE rvbbit.calliope_sessions SET {','.join(updates)},updated_at=now() "
                "WHERE id=%s::uuid AND owner_email=%s RETURNING *",
                values,
            ).fetchone()
        if "title" in body:
            await _sync_hermes_session_title(
                config,
                row.get("hermes_session_id"),
                row.get("title"),
            )
        return json_response({"session": _session_json(row)})

    @mcp.custom_route("/api/calliope/attachments/{attachment_id}", methods=["GET"])
    async def get_attachment(request):
        owner, err = api_owner(request)
        if err:
            return err
        aid = _uuid(request.path_params["attachment_id"])
        if not aid:
            return Response(status_code=404)
        with conn_factory() as conn:
            row = conn.execute(
                "SELECT a.* FROM rvbbit.calliope_attachments a "
                "WHERE a.id=%s::uuid "
                "AND rvbbit.calliope_session_can_view(a.session_id,%s,false)",
                (aid, owner),
            ).fetchone()
        if not row:
            return Response(status_code=404)
        path = Path(row["storage_path"]).resolve()
        try:
            path.relative_to(config.file_root.resolve())
        except ValueError:
            return Response(status_code=404)
        if not path.is_file():
            return Response(status_code=404)
        return FileResponse(
            path,
            media_type=row["mime_type"],
            filename=row.get("original_name") or path.name,
            content_disposition_type="inline",
            headers={
                "cache-control": "private, no-store",
                "x-content-type-options": "nosniff",
            },
        )

    @mcp.custom_route("/api/calliope/files/{surface_id}", methods=["GET"])
    async def get_surface_file(request):
        owner, err = api_owner(request)
        if err:
            return err
        surface_id = _uuid(request.path_params["surface_id"])
        if not surface_id:
            return Response(status_code=404)
        with conn_factory() as conn:
            row = conn.execute(
                "SELECT f.* FROM rvbbit.calliope_surfaces f "
                "WHERE f.id=%s::uuid AND f.kind='document' "
                "AND rvbbit.calliope_session_can_view(f.session_id,%s,false)",
                (surface_id, owner),
            ).fetchone()
        if not row:
            return Response(status_code=404)
        payload = dict(row.get("payload") or {})
        path = None
        stored = payload.get("storage_path")
        if stored:
            try:
                candidate = Path(str(stored)).resolve(strict=True)
                candidate.relative_to((config.file_root / "files").resolve())
                if candidate.is_file():
                    path = candidate
            except (OSError, RuntimeError, ValueError):
                path = None

        # Older document surfaces stored only the originating local path.
        # Copy those lazily so already-created PDFs/decks become downloadable
        # without rewriting the immutable surface ledger.
        if path is None:
            source = payload.get("source_path") or payload.get("path")
            published = _copy_export_file(source, config, str(row["session_id"]))
            if not published:
                return Response(status_code=404)
            payload.update(published)
            path = Path(published["storage_path"])
            with conn_factory() as conn:
                conn.execute(
                    "UPDATE rvbbit.calliope_surfaces SET payload=%s::jsonb WHERE id=%s::uuid",
                    (json.dumps(payload, default=str), surface_id),
                )

        filename = str(payload.get("original_name") or path.name)
        return FileResponse(
            path,
            media_type=payload.get("mime_type") or mimetypes.guess_type(filename)[0],
            filename=filename,
            content_disposition_type="attachment",
            headers={
                "cache-control": "private, no-store",
                "x-content-type-options": "nosniff",
            },
        )

    @mcp.custom_route(
        "/api/calliope/sessions/{session_id}/surfaces/{surface_id}/capture",
        methods=["POST"],
    )
    async def capture_artifact_surface(request):
        """Resolve or render the exact-version image companion used by Markup."""
        owner, err = api_owner(request)
        if err:
            return err
        session = _session_for_owner(
            conn_factory,
            request.path_params["session_id"],
            owner,
        )
        surface_id = _uuid(request.path_params["surface_id"])
        if not session or not surface_id:
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        with conn_factory() as conn:
            artifact = conn.execute(
                "SELECT * FROM rvbbit.calliope_surfaces "
                "WHERE id=%s::uuid AND session_id=%s::uuid AND kind='artifact'",
                (surface_id, str(session["id"])),
            ).fetchone()
        if not artifact:
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        artifact = dict(artifact)
        payload = artifact.get("payload") if isinstance(artifact.get("payload"), dict) else {}
        slug = str(artifact.get("artifact_slug") or payload.get("slug") or "").strip()
        try:
            version = int(artifact.get("artifact_version") or payload.get("version") or 0)
        except (TypeError, ValueError):
            version = 0
        if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{0,127}", slug, re.I) or version < 1:
            return json_response(
                {
                    "error": {
                        "code": "CAPTURE_UNAVAILABLE",
                        "message": "This artifact does not have an exact version to capture.",
                    }
                },
                409,
            )

        with conn_factory() as conn:
            allowed = conn.execute(
                "SELECT 1 FROM rvbbit.dashboards d WHERE d.slug=%s "
                "AND rvbbit.artifact_can_view(d.id,%s,false)",
                (slug, owner),
            ).fetchone()
        if not allowed:
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)

        # Reuse a durable exact-version capture when one is already present.
        # Markup derivatives intentionally do not qualify as base companions.
        with conn_factory() as conn:
            candidates = conn.execute(
                "SELECT * FROM rvbbit.calliope_surfaces "
                "WHERE session_id=%s::uuid AND kind='image' "
                "AND artifact_slug=%s AND artifact_version=%s "
                "ORDER BY created_at DESC,ordinal DESC LIMIT 12",
                (str(session["id"]), slug, version),
            ).fetchall()
        for candidate in candidates:
            source = candidate.get("source") if isinstance(candidate.get("source"), dict) else {}
            presentation = (
                candidate.get("presentation")
                if isinstance(candidate.get("presentation"), dict)
                else {}
            )
            if not (
                _canonical_tool(candidate.get("tool_name")) == "capture_live_app"
                or source.get("origin") == "calliope_markup_capture"
                or presentation.get("companion") is True
            ):
                continue
            resolved = _surface_json(candidate)
            if (resolved.get("payload") or {}).get("image_url"):
                return json_response({"surface": resolved, "reused": True})

        if artifact_capture is None:
            return json_response(
                {
                    "error": {
                        "code": "CAPTURE_UNAVAILABLE",
                        "message": "Exact-version artifact capture is not configured.",
                    }
                },
                503,
            )
        auth_session = auth.read_session_full(request) or {}
        try:
            result = await asyncio.to_thread(
                artifact_capture,
                slug,
                version,
                auth_session.get("sub"),
                owner,
            )
            if inspect.isawaitable(result):
                result = await result
        except Exception as exc:
            result = {
                "error": {
                    "code": "CAPTURE_FAILED",
                    "message": f"{type(exc).__name__}: {exc}"[:600],
                }
            }
        result = result if isinstance(result, dict) else {}
        if result.get("error"):
            error = result["error"] if isinstance(result["error"], dict) else {}
            code = str(error.get("code") or "CAPTURE_FAILED")
            status = 404 if code == "VERSION_NOT_FOUND" else 503 if code == "CAPTURE_UNAVAILABLE" else 502
            return json_response(
                {
                    "error": {
                        "code": code,
                        "message": str(error.get("message") or "The artifact snapshot failed.")[:600],
                    }
                },
                status,
            )

        projected = _publish_local_files(
            [{
                "kind": "image",
                "title": f"Capture · {artifact.get('title') or slug}"[:240],
                "tool_name": "calliope_artifact_capture",
                "tool_call_id": f"markup-capture:{surface_id}:{uuid.uuid4().hex[:12]}",
                "lineage_key": f"capture:{slug}",
                "parent_surface_id": surface_id,
                "artifact_slug": slug,
                "artifact_version": version,
                "payload": result,
                "source": {
                    "origin": "calliope_markup_capture",
                    "source_surface_id": surface_id,
                },
                "presentation": {"companion": True, "purpose": "markup"},
            }],
            [],
            "",
            config,
            str(session["id"]),
            str(artifact["turn_id"]),
        )
        stored_payload = projected[0].get("payload") if projected else {}
        if not isinstance(stored_payload, dict) or not stored_payload.get("storage_path"):
            return json_response(
                {
                    "error": {
                        "code": "CAPTURE_UNAVAILABLE",
                        "message": "The rendered snapshot could not be retained for markup.",
                    }
                },
                503,
            )
        inserted = _insert_surfaces(
            conn_factory,
            str(session["id"]),
            str(artifact["turn_id"]),
            projected,
        )
        if not inserted:
            return json_response(
                {"error": {"code": "CAPTURE_STORE_FAILED"}},
                500,
            )
        return json_response({"surface": inserted[0], "reused": False}, 201)

    @mcp.custom_route("/api/calliope/surfaces/{surface_id}/image", methods=["GET"])
    async def get_surface_image(request):
        owner, err = api_owner(request)
        if err:
            return err
        surface_id = _uuid(request.path_params["surface_id"])
        if not surface_id:
            return Response(status_code=404)
        with conn_factory() as conn:
            row = conn.execute(
                "SELECT f.session_id,f.payload "
                "FROM rvbbit.calliope_surfaces f "
                "WHERE f.id=%s::uuid AND f.kind='image' "
                "AND rvbbit.calliope_session_can_view(f.session_id,%s,false)",
                (surface_id, owner),
            ).fetchone()
        if not row:
            return Response(status_code=404)
        payload = dict(row.get("payload") or {})
        attachment_id = _uuid(payload.get("attachment_id"))
        media_type = None
        allowed_roots: tuple[Path, ...] = ()
        path = None
        if attachment_id:
            with conn_factory() as conn:
                attachment = conn.execute(
                    "SELECT storage_path,mime_type FROM rvbbit.calliope_attachments "
                    "WHERE id=%s::uuid AND session_id=%s::uuid",
                    (attachment_id, str(row["session_id"])),
                ).fetchone()
            if attachment:
                path = Path(attachment["storage_path"]).resolve()
                media_type = str(attachment["mime_type"])
                allowed_roots = (config.file_root.resolve(),)
        else:
            stored = payload.get("storage_path")
            if stored:
                try:
                    path = Path(str(stored)).resolve(strict=True)
                    path.relative_to((config.file_root / "captures").resolve())
                    allowed_roots = ((config.file_root / "captures").resolve(),)
                except (OSError, RuntimeError, ValueError):
                    path = None
            if path is None:
                capture_path = payload.get("source_path") or payload.get("path")
                published = _copy_capture_file(
                    capture_path,
                    config,
                    str(row["session_id"]),
                )
                if published:
                    payload.update(published)
                    path = Path(published["storage_path"]).resolve()
                    allowed_roots = ((config.file_root / "captures").resolve(),)
                    with conn_factory() as conn:
                        conn.execute(
                            "UPDATE rvbbit.calliope_surfaces SET payload=%s::jsonb "
                            "WHERE id=%s::uuid",
                            (json.dumps(payload, default=str), surface_id),
                        )
                elif capture_path:
                    try:
                        candidate = Path(str(capture_path)).resolve(strict=True)
                    except (OSError, RuntimeError):
                        candidate = None
                    if candidate and any(
                        _is_relative_to(candidate, root)
                        for root in _capture_source_roots()
                    ):
                        path = candidate
                        allowed_roots = _capture_source_roots()
            if path:
                media_type = {
                    ".png": "image/png",
                    ".jpg": "image/jpeg",
                    ".jpeg": "image/jpeg",
                    ".webp": "image/webp",
                    ".gif": "image/gif",
                }.get(path.suffix.lower())
        if not path or not allowed_roots or not media_type:
            return Response(status_code=404)
        if not any(_is_relative_to(path, root) for root in allowed_roots):
            return Response(status_code=404)
        if not path.is_file():
            return Response(status_code=404)
        return FileResponse(
            path,
            media_type=media_type,
            headers={
                "cache-control": "private, no-store",
                "x-content-type-options": "nosniff",
            },
        )

    @mcp.custom_route(
        "/calliope/artifacts/{slug}/versions/{version}",
        methods=["GET"],
    )
    async def artifact_version(request):
        owner, session = _canonical_owner(request)
        if not owner:
            return RedirectResponse(f"/login?next={quote(request.url.path)}", status_code=302)
        if not session.get("mapped", True):
            return RedirectResponse("/gallery", status_code=302)
        slug = request.path_params["slug"]
        if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{0,127}", slug, re.I):
            return artifact_not_found_response(owner, session)
        try:
            version = int(request.path_params["version"])
        except (TypeError, ValueError):
            return artifact_not_found_response(owner, session)
        shared_session_id = _uuid(request.query_params.get("session"))
        with conn_factory() as conn:
            row = conn.execute(
                "SELECT v.html,v.manifest FROM rvbbit.dashboards d "
                "JOIN rvbbit.dashboard_versions v ON v.dashboard_id=d.id "
                "WHERE d.slug=%s AND v.version=%s AND ("
                " (NOT d.archived AND rvbbit.artifact_can_view(d.id,%s,false))"
                " OR (%s::uuid IS NOT NULL AND EXISTS ("
                "  SELECT 1 FROM rvbbit.calliope_surfaces f"
                "  WHERE f.session_id=%s::uuid AND f.kind='artifact'"
                "  AND f.artifact_slug=d.slug AND f.artifact_version=v.version"
                "  AND rvbbit.calliope_session_can_view(f.session_id,%s,false)"
                " )))",
                (
                    slug, version, owner, shared_session_id,
                    shared_session_id, owner,
                ),
            ).fetchone()
        if not row:
            return artifact_not_found_response(owner, session)
        embedded = request.query_params.get("embed") == "1"
        return HTMLResponse(
            _artifact_version_document(
                slug,
                version,
                row["html"] or "",
                artifact_shim,
                embedded,
                row.get("manifest") or {},
            ),
            headers={
                "cache-control": "no-store",
                "content-security-policy": _artifact_version_csp(embedded),
                "x-content-type-options": "nosniff",
            },
        )

    @mcp.custom_route("/api/calliope/sessions/{session_id}/turn", methods=["POST"])
    async def run_turn(request):
        owner, err = api_owner(request)
        if err:
            return err
        signed_profile = observe_browser_principal(request) or {}
        author_display_name = (
            re.sub(r"\s+", " ", str(signed_profile.get("name") or "")).strip()[:160]
            or owner
        )
        session = _session_for_owner(conn_factory, request.path_params["session_id"], owner)
        if not session:
            return json_response({"error": {"code": "NOT_FOUND"}}, 404)
        try:
            body = await request.json()
        except Exception:
            body = {}
        if not isinstance(body, dict):
            body = {}
        submitted_client_turn_id = body.get("client_turn_id")
        client_turn_id = _uuid(submitted_client_turn_id)
        if submitted_client_turn_id not in (None, "") and not client_turn_id:
            return json_response(
                {"error": {"code": "INVALID_CLIENT_TURN_ID"}},
                400,
            )
        if body.get("reattach") is True:
            if not client_turn_id:
                return json_response(
                    {"error": {"code": "CLIENT_TURN_ID_REQUIRED"}},
                    400,
                )
            with conn_factory() as conn:
                existing = conn.execute(
                    "SELECT * FROM rvbbit.calliope_turns "
                    "WHERE session_id=%s::uuid AND client_turn_id=%s::uuid",
                    (str(session["id"]), client_turn_id),
                ).fetchone()
            if not existing:
                return json_response(
                    {"error": {"code": "TURN_NOT_FOUND"}},
                    404,
                )
            return await existing_turn_response(dict(existing), request)
        client_turn_id = client_turn_id or str(uuid.uuid4())
        request_fingerprint = _turn_request_fingerprint(body)
        raw_message = str((body or {}).get("message") or "").strip()
        if len(raw_message) > 40_000:
            return json_response({"error": {"code": "MESSAGE_TOO_LONG"}}, 400)
        requested_playbook_source = (body or {}).get("playbook_source_turn_id")
        playbook_source_turn_id = None
        if requested_playbook_source not in (None, ""):
            playbook_source_turn_id = _uuid(requested_playbook_source)
            if not playbook_source_turn_id:
                return json_response(
                    {"error": {"code": "INVALID_PLAYBOOK_SOURCE_TURN"}},
                    400,
                )
            with conn_factory() as conn:
                source_turn = conn.execute(
                    "SELECT id FROM rvbbit.calliope_turns "
                    "WHERE id=%s::uuid AND session_id=%s::uuid AND turn_kind='chat' "
                    "AND status IN ('complete','partial')",
                    (playbook_source_turn_id, str(session["id"])),
                ).fetchone()
            if not source_turn:
                return json_response(
                    {"error": {"code": "PLAYBOOK_SOURCE_TURN_NOT_FOUND"}},
                    404,
                )
        try:
            object_markers = _composer_object_markers(raw_message)
            submitted_object_handles = _decode_composer_object_handles(
                (body or {}).get("object_refs")
            )
            marker_keys = {
                (item["kind"], item["ref_id"]) for item in object_markers
            }
            submitted_keys = {
                (item["kind"], item["ref_id"])
                for item in submitted_object_handles
            }
            if submitted_object_handles and submitted_keys != marker_keys:
                raise ValueError(
                    "Composer object handles do not match the references in the message"
                )
            object_refs = _resolve_composer_objects(
                conn_factory, owner, object_markers
            )
            message = _composer_plain_text(raw_message).strip()
        except ValueError as exc:
            return json_response(
                {
                    "error": {
                        "code": "BAD_OBJECT_REFERENCE",
                        "message": str(exc),
                    }
                },
                400,
            )
        try:
            decoded = _decode_attachments((body or {}).get("attachments"), config)
        except ValueError as exc:
            return json_response({"error": {"code": "BAD_ATTACHMENT", "message": str(exc)}}, 400)
        try:
            spatial_selections = _decode_spatial_selections(
                (body or {}).get("spatial_selections")
            )
        except ValueError as exc:
            return json_response(
                {"error": {"code": "BAD_SPATIAL_SELECTION", "message": str(exc)}},
                400,
            )
        try:
            evidence_handles = _decode_evidence_handles(
                (body or {}).get("evidence_refs")
            )
            evidence_refs = _hydrate_evidence_refs(
                conn_factory,
                str(session["id"]),
                evidence_handles,
            )
        except ValueError as exc:
            return json_response(
                {"error": {"code": "BAD_EVIDENCE_REFERENCE", "message": str(exc)}},
                400,
            )
        if (
            not message and not decoded and not spatial_selections
            and not evidence_refs and not object_refs
        ):
            return json_response({"error": {"code": "EMPTY_MESSAGE"}}, 400)
        try:
            annotation_sources = _annotation_sources(
                conn_factory,
                str(session["id"]),
                decoded,
            )
        except ValueError as exc:
            return json_response({"error": {"code": "BAD_ATTACHMENT", "message": str(exc)}}, 400)
        try:
            spatial_sources = _spatial_sources(
                conn_factory,
                str(session["id"]),
                spatial_selections,
            )
        except ValueError as exc:
            return json_response(
                {"error": {"code": "BAD_SPATIAL_SELECTION", "message": str(exc)}},
                400,
            )

        selected_id = _uuid((body or {}).get("selected_surface_id"))
        selected_profile_version_id = None
        if selected_id:
            with conn_factory() as conn:
                selected_ok = conn.execute(
                    "SELECT design_profile_version_id FROM rvbbit.calliope_surfaces "
                    "WHERE id=%s::uuid AND session_id=%s::uuid",
                    (selected_id, str(session["id"])),
                ).fetchone()
            if not selected_ok:
                selected_id = None
            elif selected_ok.get("design_profile_version_id"):
                selected_profile_version_id = str(
                    selected_ok["design_profile_version_id"]
                )

        if "design_profile_version_id" in body:
            requested_profile = body.get("design_profile_version_id")
            design_profile_version_id = _uuid(requested_profile)
            if requested_profile not in (None, "") and not design_profile_version_id:
                return json_response(
                    {"error": {"code": "INVALID_DESIGN_PROFILE"}},
                    400,
                )
            if design_profile_version_id and not _design_profile_version(
                conn_factory,
                design_profile_version_id,
                active_only=True,
            ):
                return json_response(
                    {"error": {"code": "DESIGN_PROFILE_NOT_FOUND"}},
                    404,
                )
        else:
            design_profile_version_id = (
                selected_profile_version_id
                or (
                    str(session["design_profile_version_id"])
                    if session.get("design_profile_version_id")
                    else None
                )
            )
        design_profile = (
            _design_profile_version(
                conn_factory,
                design_profile_version_id,
            )
            if design_profile_version_id
            else None
        )
        if design_profile_version_id and not design_profile:
            design_profile_version_id = None

        turn_id = str(uuid.uuid4())
        existing_turn: dict[str, Any] | None = None
        with conn_factory() as conn:
            with conn.transaction():
                conn.execute(
                    "SELECT id FROM rvbbit.calliope_sessions WHERE id=%s::uuid FOR UPDATE",
                    (str(session["id"]),),
                )
                existing = conn.execute(
                    "SELECT * FROM rvbbit.calliope_turns "
                    "WHERE session_id=%s::uuid AND client_turn_id=%s::uuid",
                    (str(session["id"]), client_turn_id),
                ).fetchone()
                if existing:
                    stored_fingerprint = str(
                        existing.get("request_fingerprint") or ""
                    )
                    if (
                        stored_fingerprint
                        and stored_fingerprint != request_fingerprint
                    ):
                        return json_response(
                            {
                                "error": {
                                    "code": "CLIENT_TURN_CONFLICT",
                                    "message": (
                                        "That browser turn ID already belongs to a "
                                        "different message."
                                    ),
                                }
                            },
                            409,
                        )
                    existing_turn = dict(existing)
                active = None if existing_turn else conn.execute(
                    "SELECT * FROM rvbbit.calliope_turns "
                    "WHERE session_id=%s::uuid AND status='running' LIMIT 1",
                    (str(session["id"]),),
                ).fetchone()
                if active:
                    if (
                        str(active.get("request_fingerprint") or "")
                        == request_fingerprint
                    ):
                        existing_turn = dict(active)
                    else:
                        return json_response(
                            {
                                "error": {
                                    "code": "TURN_IN_PROGRESS",
                                    "message": (
                                        "Calliope is still working on the original "
                                        "turn in this session."
                                    ),
                                    "turn_id": str(active["id"]),
                                }
                            },
                            409,
                        )
                if existing_turn:
                    next_ordinal = int(existing_turn["ordinal"])
                    turn_id = str(existing_turn["id"])
                else:
                    next_ordinal = conn.execute(
                        "SELECT coalesce(max(ordinal),0)+1 AS n FROM rvbbit.calliope_turns "
                        "WHERE session_id=%s::uuid",
                        (str(session["id"]),),
                    ).fetchone()["n"]
                    conn.execute(
                        "INSERT INTO rvbbit.calliope_turns "
                        "(id,session_id,client_turn_id,request_fingerprint,ordinal,"
                        "user_message,selected_surface_id,design_profile_version_id,"
                        "evidence_refs,object_refs,author_email,author_display_name,"
                        "playbook_source_turn_id) "
                        "VALUES (%s::uuid,%s::uuid,%s::uuid,%s,%s,%s,%s::uuid,"
                        "%s::uuid,%s::jsonb,%s::jsonb,%s,%s,%s::uuid)",
                        (
                            turn_id,
                            str(session["id"]),
                            client_turn_id,
                            request_fingerprint,
                            next_ordinal,
                            message or (
                                "[Object selection]" if spatial_selections
                                else "[Image]" if decoded
                                else "[Selected evidence]" if evidence_refs
                                else "[Referenced object]"
                            ),
                            selected_id,
                            design_profile_version_id,
                            json.dumps(evidence_refs, default=str),
                            json.dumps(object_refs, default=str),
                            owner,
                            author_display_name,
                            playbook_source_turn_id,
                        ),
                    )
                    conn.execute(
                        "UPDATE rvbbit.calliope_sessions SET updated_at=now() WHERE id=%s::uuid",
                        (str(session["id"]),),
                    )

        if existing_turn:
            return await existing_turn_response(existing_turn, request)

        setup_instruction_context = None
        if str(session.get("purpose") or "chat") == "setup":
            requested_setup_item = str(body.get("setup_item") or "").strip().lower()
            try:
                setup_can_manage = await asyncio.to_thread(
                    calliope_dreams.is_company_admin, conn_factory, owner
                )
                setup_snapshot = await asyncio.to_thread(
                    _setup_workspace_snapshot,
                    conn_factory,
                    owner,
                    session,
                    can_manage=setup_can_manage,
                )
                setup_instruction_context = _setup_instruction_context(
                    setup_snapshot,
                    active_item=requested_setup_item,
                )
            except Exception:
                setup_instruction_context = {
                    "available": False,
                    "error": "The deterministic setup state could not be read for this turn.",
                }

        try:
            stored_attachments = _persist_attachments(
                conn_factory,
                config,
                str(session["id"]),
                turn_id,
                decoded,
            )
        except Exception as exc:
            _complete_turn(conn_factory, turn_id, "", None, "failed", str(exc)[:600])
            return json_response({"error": {"code": "ATTACHMENT_STORE_FAILED"}}, 500)

        try:
            input_surfaces = _insert_surfaces(
                conn_factory,
                str(session["id"]),
                turn_id,
                [
                    *_annotation_surface_projections(decoded, annotation_sources),
                    *_spatial_selection_projections(spatial_selections, spatial_sources),
                ],
            )
        except Exception as exc:
            _complete_turn(conn_factory, turn_id, "", None, "failed", str(exc)[:600])
            return json_response({"error": {"code": "INPUT_SURFACE_STORE_FAILED"}}, 500)

        compact, selected = _compact_surface_context(
            conn_factory,
            str(session["id"]),
            selected_id,
        )
        selected_context = _selected_surface_context_text(selected)
        selected_sketch_image = _selected_sketch_image_context(
            conn_factory,
            config,
            str(session["id"]),
            selected,
        )
        spatial_context = _spatial_context_text(spatial_selections, spatial_sources)
        evidence_context = _evidence_context_text(evidence_refs)
        object_context = _composer_object_context_text(object_refs)
        work_routing_context = (
            "[CALLIOPE WORK ROUTING — internal]\n"
            f"Originating Calliope session_id: {session['id']}\n"
            f"Current Calliope turn_id: {turn_id}\n"
            "Use the RVBBIT MCP tool calliope_work_item with this exact session_id when "
            "you create a persistent goal, reach a meaningful async "
            "result, become blocked, or identify a genuinely useful proactive suggestion. "
            "Do not publish routine tool progress. Never create a raw Hermes cron job for a "
            "Calliope user. For one-time or recurring private work assigned to Callie, clarify "
            "the outcome, time or cadence, useful inert context, and notification preference, "
            "then call draft_calliope_work_order with this session_id. Default to read_only and "
            "notification_policy attention. It creates a private human-reviewable draft in "
            "Assigned to Callie; only the human can activate its managed Hermes schedule. "
            "When the user wants to discover, connect, install, repair, or configure an organization "
            "capability, use search_calliope_actions with this session_id. If the signed-in user is "
            "an administrator, call administer_calliope_action directly for every typed appliance "
            "installation, configuration, repair, mirror-control, Company Brain source, or credential "
            "action. It creates the durable audit receipt itself, applies, tests, and returns exact "
            "failed-step evidence without a plan or approval ceremony. Do not ask the user to approve "
            "a plan or reconfirm an already requested outcome. If it reports secure_input_required, "
            "send the user only to the native secure field for the named missing value; submitting that "
            "form applies and verifies the action directly. Never ask for or pass a credential in chat "
            "or tool arguments. Credential revocation needs no native form and should be executed "
            "directly when requested. For local RVBBIT database administration that has no narrower "
            "typed action, use administer_local_sql with this exact session_id. Keep ordinary reads "
            "on run_sql. A SELECT/WITH-shaped administration statement, including an RVBBIT function "
            "that writes settings or catalogs, executes directly. For explicit DDL, DML, CALL, DO, "
            "GRANT, or REVOKE, the first call freezes the exact SQL and returns approval_required. "
            "Show that SQL to the user and wait for explicit approval, then call administer_local_sql "
            "again with approved_run_id only. Never put credentials or remote source DSNs in SQL; "
            "remote database access remains with dlt. Use "
            "mirror_status for local mirror schedules, controller health, and durable run status. "
            "Mirror actions operate only on the local dlt control plane: neither Hermes nor a direct "
            "assistant path may contact the production source database. "
            "When the user asks who can see this notebook or asks to share/unshare it, use "
            "calliope_session_access_get and calliope_session_access_update with the exact "
            "originating session_id above. Explain that recipients are view-only, inspect the "
            "current revision first, never infer an email, and require explicit confirmation "
            "before adding Everyone. "
            "When the user wants to make a repeatable workflow into a small reusable interface, "
            "co-design it and call draft_calliope_instrument with this session_id; that creates "
            "a private human-reviewable draft and never publishes it automatically. When the "
            "work is a reusable governed automation with explicit contexts, requirements, and "
            "outputs rather than a personal assignment, co-design a bounded "
            "Calliope Workflow and call draft_calliope_workflow with this session_id. Keep one "
            "agent goal, governed context, and explicit outputs rather than a low-level tool DAG; "
            "the result is also a private draft that the human must publish and schedule. "
            "A Playbook is a fuzzy reusable method learned from successful work, not a tool DAG. "
            "When repeatable multi-step work resembles an existing method, use capability_search "
            "under the inherited caller identity. If a relevant cap_playbook is returned, load its "
            "exact approved version with read_calliope_playbook before applying it, briefly tell the "
            "human which Playbook and version you are using, adapt its method to current capabilities, "
            "and validate its completion criteria. Never claim to have used a Playbook you did not load. "
            "When the human asks to remember or revise a useful method, call draft_calliope_playbook "
            "with this session_id and the exact current or explicitly supplied source turn_id. Keep it "
            "private and outcome-focused; never call approve_calliope_playbook unless a human has "
            "explicitly requested approval in the current turn. "
            "This request originates in the Calliope web notebook, so you may proactively use "
            "the thread's Sketch without waiting for an explicit diagram request whenever a "
            "diagram, spatial explanation, process map, comparison, or shared visual scratchpad "
            "would materially help. Do not use it reflexively when prose or an existing surface is "
            "already clearer. Ordinary web notebooks already have one empty minimized canvas. "
            "When the recent surface state contains its sketch receipt, read that canvas and use "
            "update_calliope_sketch; use create_calliope_sketch only if no receipt exists. There is "
            "only one Sketch per session. Read its latest revision after human edits; preserve useful existing "
            "elements and use typed operations instead of replacing or authoring raw scene JSON.\n"
            "[/CALLIOPE WORK ROUTING]"
        )
        playbook_distillation_context = (
            "[CALLIOPE PLAYBOOK DISTILLATION — internal]\n"
            "The human explicitly clicked Save as Playbook for the completed response "
            f"{playbook_source_turn_id}. Distill the durable method learned through that response. "
            "Call draft_calliope_playbook exactly once with the originating session_id and "
            f"source_turn_id={playbook_source_turn_id}. Preserve outcomes, applicability, judgment, "
            "guardrails, validation, fallbacks, and capability needs; omit transient IDs, one-off values, "
            "and accidental tool order. Create a private draft only. Do not approve or share it. "
            "Explain any blocked or degraded capability needs in the resulting review card.\n"
            "[/CALLIOPE PLAYBOOK DISTILLATION]"
            if playbook_source_turn_id else ""
        )
        prompt_text = "\n\n".join(
            part
            for part in (
                message,
                selected_context,
                object_context,
                spatial_context,
                evidence_context,
                playbook_distillation_context,
                work_routing_context,
            )
            if part
        )
        if decoded or selected_sketch_image:
            hermes_message: Any = []
            if prompt_text:
                hermes_message.append({"type": "text", "text": prompt_text})
            hermes_message.extend({
                "type": "image_url",
                "image_url": {"url": item["data_url"], "detail": "high"},
            } for item in decoded)
            if selected_sketch_image:
                hermes_message.append(selected_sketch_image)
        else:
            hermes_message = prompt_text

        workflow_trace_run_id = _active_manual_workflow_run_id(
            conn_factory, str(session["id"])
        )

        async def stream() -> AsyncIterator[bytes]:
            assistant_text = ""
            hermes_message_id = None
            effective_hermes_id = str(session["hermes_session_id"])
            completed = False
            upstream_error = None
            turn_messages: list[dict[str, Any]] = []
            all_turn_messages: list[dict[str, Any]] = []
            observed_tools: list[dict[str, Any]] = []
            published_links: dict[str, tuple[str, str]] = {}
            suppress_assistant_deltas = False
            delta_probe = ""
            yield _sse("calliope.turn.started", {
                "turn_id": turn_id,
                "client_turn_id": client_turn_id,
                "ordinal": next_ordinal,
                "author": {
                    "email": owner,
                    "display_name": author_display_name,
                    "avatar_url": "/auth/avatar",
                },
                "attachments": stored_attachments,
                "evidence_refs": evidence_refs,
                "object_refs": object_refs,
                "design_profile": _design_profile_snapshot(design_profile),
            })
            if input_surfaces:
                yield _sse("calliope.surfaces", {
                    "turn_id": turn_id,
                    "surfaces": input_surfaces,
                })
            timeout = httpx.Timeout(None, connect=10.0, write=45.0, pool=10.0)
            cost_receipts: list[dict[str, Any]] = []
            try:
                next_hermes_message = hermes_message
                feedback_count = 0
                inserted_surface_count = len(input_surfaces)
                async with httpx.AsyncClient(timeout=timeout) as client:
                    for hop in range(_VISUAL_FEEDBACK_BUDGET + 1):
                        hop_started = time.monotonic()
                        if hop:
                            assistant_text = ""
                            yield _sse("calliope.visual_check", {
                                "turn_id": turn_id,
                                "number": feedback_count,
                                "budget": _VISUAL_FEEDBACK_BUDGET,
                            })
                        completed = False
                        upstream_error = None
                        turn_messages = []
                        hop_usage: dict[str, Any] = {}
                        hop_runtime: dict[str, Any] = {}
                        suppress_assistant_deltas = False
                        delta_probe = ""
                        hop_compact, hop_selected = (
                            (compact, selected)
                            if hop == 0
                            else _compact_surface_context(
                                conn_factory,
                                str(session["id"]),
                                selected_id,
                            )
                        )
                        url = _hermes_session_url(
                            config,
                            effective_hermes_id,
                            "/chat/stream",
                        )
                        async with client.stream(
                            "POST",
                            url,
                            headers=_hermes_headers(config),
                            json={
                                "message": next_hermes_message,
                                "instructions": _instructions(
                                    hop_compact,
                                    hop_selected,
                                    config.export_roots,
                                    design_profile,
                                    setup_mode=(
                                        str(session.get("purpose") or "chat") == "setup"
                                    ),
                                    setup_context=setup_instruction_context,
                                ),
                            },
                        ) as upstream:
                            if upstream.status_code >= 400:
                                raw = (await upstream.aread()).decode(errors="replace")[:900]
                                raise RuntimeError(
                                    f"Hermes turn failed ({upstream.status_code}): {raw}"
                                )
                            async for event, data in _iter_sse(upstream):
                                if event is None:
                                    yield b": keepalive\n\n"
                                    continue
                                skip_forward = False
                                if isinstance(data, dict):
                                    if data.get("session_id"):
                                        effective_hermes_id = str(data["session_id"])
                                    if event == "assistant.delta":
                                        delta = str(data.get("delta") or "")
                                        delta_probe = (delta_probe + delta)[-96:]
                                        if (
                                            "data:image/" in delta_probe.lower()
                                            or re.search(r"!\[[^\]]{0,60}\]\($", delta_probe)
                                        ):
                                            suppress_assistant_deltas = True
                                        if not suppress_assistant_deltas:
                                            assistant_text = _sanitize_assistant_text(
                                                assistant_text + delta
                                            )
                                        else:
                                            skip_forward = True
                                    elif event == "assistant.completed":
                                        assistant_text = _sanitize_assistant_text(
                                            data.get("content") or assistant_text
                                        )
                                        if (
                                            "session storage could not be written"
                                            in assistant_text.lower()
                                            and "state.db" in assistant_text.lower()
                                        ):
                                            assistant_text = _friendly_turn_stream_error(
                                                assistant_text
                                            )
                                        data = {**data, "content": assistant_text}
                                        hermes_message_id = (
                                            data.get("message_id") or hermes_message_id
                                        )
                                        if isinstance(data.get("runtime"), dict):
                                            hop_runtime = dict(data["runtime"])
                                    elif event == "run.completed":
                                        completed = True
                                        hermes_message_id = (
                                            data.get("message_id") or hermes_message_id
                                        )
                                        if isinstance(data.get("messages"), list):
                                            turn_messages = data["messages"]
                                        if isinstance(data.get("usage"), dict):
                                            hop_usage = dict(data["usage"])
                                        if isinstance(data.get("runtime"), dict):
                                            hop_runtime = dict(data["runtime"])
                                        # The interleaved transcript can contain
                                        # rowsets, HTML, paths, and image bytes. It
                                        # is server-side projection input, never a
                                        # browser/chat event.
                                        skip_forward = True
                                    elif event == "tool.progress":
                                        # Hermes derives this _thinking event from
                                        # user-visible assistant content, not from
                                        # provider-native hidden reasoning.
                                        note = (
                                            _sanitize_working_note(
                                                data.get("delta") or data.get("preview")
                                            )
                                            if str(data.get("tool_name") or "") == "_thinking"
                                            else ""
                                        )
                                        if note:
                                            event = "calliope.progress"
                                            data = {"text": note}
                                        else:
                                            skip_forward = True
                                    elif event == "tool.started":
                                        tool_name = str(
                                            data.get("tool_name") or "warehouse tool"
                                        )
                                        tool_preview = str(data.get("preview") or "")[:240]
                                        if workflow_trace_run_id:
                                            _try_record_workflow_runtime_step(
                                                conn_factory,
                                                workflow_trace_run_id,
                                                event,
                                                tool_name,
                                                tool_preview,
                                            )
                                        data = {
                                            "tool_name": tool_name,
                                            "preview": tool_preview,
                                        }
                                    elif event == "tool.completed":
                                        tool_name = str(
                                            data.get("tool_name") or "warehouse tool"
                                        )
                                        observed_tools.append({
                                            "name": tool_name,
                                            "call_id": str(data.get("call_id") or ""),
                                            "status": "complete",
                                        })
                                        if workflow_trace_run_id:
                                            _try_record_workflow_runtime_step(
                                                conn_factory,
                                                workflow_trace_run_id,
                                                event,
                                                tool_name,
                                            )
                                        data = {
                                            "tool_name": tool_name,
                                            "call_id": str(data.get("call_id") or ""),
                                        }
                                    elif event == "tool.failed":
                                        tool_name = str(
                                            data.get("tool_name") or "warehouse tool"
                                        )
                                        observed_tools.append({
                                            "name": tool_name,
                                            "call_id": str(data.get("call_id") or ""),
                                            "status": "failed",
                                        })
                                        tool_message = _sanitize_working_note(
                                            data.get("preview") or "Tool call failed"
                                        )
                                        if workflow_trace_run_id:
                                            _try_record_workflow_runtime_step(
                                                conn_factory,
                                                workflow_trace_run_id,
                                                event,
                                                tool_name,
                                                tool_message,
                                            )
                                        data = {
                                            "tool_name": tool_name,
                                            "message": tool_message,
                                        }
                                    elif event == "error":
                                        upstream_error = str(
                                            data.get("message")
                                            or data.get("error")
                                            or "Hermes turn failed"
                                        )
                                        data = {"message": upstream_error[:900]}
                                    elif event not in {"assistant.delta", "assistant.completed"}:
                                        skip_forward = True
                                if not skip_forward:
                                    yield _sse(event, data)

                        if upstream_error:
                            raise RuntimeError(upstream_error)
                        all_turn_messages.extend(turn_messages)
                        if completed:
                            try:
                                receipt = await asyncio.to_thread(
                                    _record_hermes_receipt,
                                    conn_factory,
                                    owner,
                                    str(session["id"]),
                                    turn_id,
                                    hop,
                                    hop_usage,
                                    hop_runtime,
                                    effective_hermes_id,
                                    hermes_message_id,
                                    round((time.monotonic() - hop_started) * 1_000),
                                )
                                if receipt:
                                    cost_receipts.append(receipt)
                            except Exception as exc:
                                print(
                                    f"WARNING: Calliope Hermes receipt failed for {turn_id}: {exc}",
                                    file=os.sys.stderr,
                                )
                        projected = _publish_local_files(
                            project_messages(turn_messages),
                            turn_messages,
                            assistant_text,
                            config,
                            str(session["id"]),
                            turn_id,
                        )
                        projected = _verify_recovered_surfaces(
                            conn_factory,
                            config,
                            turn_id,
                            projected,
                        )
                        projected = _attribute_turn_artifacts(
                            conn_factory,
                            owner,
                            turn_id,
                            projected,
                            design_profile,
                        )
                        hop_surfaces = _insert_surfaces(
                            conn_factory,
                            str(session["id"]),
                            turn_id,
                            projected,
                        )
                        published_links.update(
                            _published_file_links(projected, hop_surfaces)
                        )
                        assistant_text = _sanitize_assistant_text(
                            _rewrite_local_file_links(assistant_text, published_links)
                        )
                        if hop_surfaces:
                            inserted_surface_count += len(hop_surfaces)
                            yield _sse("calliope.surfaces", {
                                "turn_id": turn_id,
                                "surfaces": hop_surfaces,
                            })
                        feedback = (
                            _capture_feedback_message(
                                projected,
                                hop_surfaces,
                                config,
                                feedback_count + 1,
                            )
                            if completed and feedback_count < _VISUAL_FEEDBACK_BUDGET
                            else None
                        )
                        if not feedback:
                            break
                        feedback_count += 1
                        next_hermes_message = feedback

                if effective_hermes_id != str(session["hermes_session_id"]):
                    with conn_factory() as conn:
                        conn.execute(
                            "UPDATE rvbbit.calliope_sessions SET hermes_session_id=%s "
                            "WHERE id=%s::uuid",
                            (effective_hermes_id, str(session["id"])),
                        )
                _complete_turn(
                    conn_factory,
                    turn_id,
                    _sanitize_assistant_text(assistant_text),
                    str(hermes_message_id) if hermes_message_id else None,
                    "complete" if completed else "partial",
                )
                workflow_fallback = _try_finalize_unfinished_manual_workflow_run(
                    conn_factory,
                    str(session["id"]),
                    assistant_text,
                    turn_status="complete" if completed else "partial",
                )
                if workflow_fallback and workflow_fallback.get("surfaces"):
                    fallback_surfaces = workflow_fallback["surfaces"]
                    inserted_surface_count += len(fallback_surfaces)
                    yield _sse("calliope.surfaces", {
                        "turn_id": turn_id,
                        "surfaces": fallback_surfaces,
                    })
                try:
                    response_receipt = _response_receipt(
                        conn_factory,
                        turn_id,
                        evidence_refs,
                        object_refs,
                        all_turn_messages,
                        observed_tools,
                    )
                    _store_response_receipt(
                        conn_factory, turn_id, response_receipt
                    )
                except Exception as exc:
                    response_receipt = {}
                    print(
                        f"WARNING: Calliope response receipt failed for {turn_id}: {exc}",
                        file=os.sys.stderr,
                    )
                _enqueue_session_synopsis(conn_factory, str(session["id"]))
                generated_title = await _maybe_generate_session_title(
                    config,
                    conn_factory,
                    str(session["id"]),
                    owner,
                )
                yield _sse("calliope.turn.completed", {
                    "turn_id": turn_id,
                    "assistant_message": _sanitize_assistant_text(assistant_text),
                    "surface_count": inserted_surface_count,
                    "visual_checks": feedback_count,
                    "cost_receipts": cost_receipts,
                    "response_receipt": response_receipt,
                    "session_title": (
                        generated_title.get("title") if generated_title else None
                    ),
                    "title_source": (
                        generated_title.get("title_source") if generated_title else None
                    ),
                })
            except asyncio.CancelledError:
                if workflow_trace_run_id:
                    _try_record_workflow_runtime_step(
                        conn_factory,
                        workflow_trace_run_id,
                        "tool.failed",
                        "Hermes agent",
                        "Warehouse stopped the foreground turn runner before it completed.",
                    )
                _complete_turn(
                    conn_factory,
                    turn_id,
                    _sanitize_assistant_text(assistant_text),
                    str(hermes_message_id) if hermes_message_id else None,
                    "interrupted",
                    "turn runner cancelled",
                )
                _enqueue_session_synopsis(conn_factory, str(session["id"]))
                _try_finalize_unfinished_manual_workflow_run(
                    conn_factory,
                    str(session["id"]),
                    assistant_text,
                    turn_status="interrupted",
                    error="turn runner cancelled",
                )
                raise
            except Exception as exc:
                message_text = _friendly_turn_stream_error(exc)
                if workflow_trace_run_id:
                    _try_record_workflow_runtime_step(
                        conn_factory,
                        workflow_trace_run_id,
                        "tool.failed",
                        "Hermes agent",
                        message_text,
                    )
                _complete_turn(
                    conn_factory,
                    turn_id,
                    _sanitize_assistant_text(assistant_text),
                    str(hermes_message_id) if hermes_message_id else None,
                    "failed",
                    message_text,
                )
                _enqueue_session_synopsis(conn_factory, str(session["id"]))
                _try_finalize_unfinished_manual_workflow_run(
                    conn_factory,
                    str(session["id"]),
                    assistant_text,
                    turn_status="failed",
                    error=message_text,
                )
                yield _sse("calliope.error", {
                    "turn_id": turn_id,
                    "message": message_text,
                })

        broker = _start_turn_stream(turn_id, stream())
        return turn_stream_response(
            _subscribe_turn_stream(broker),
            request=request,
            turn_id=turn_id,
            client_turn_id=client_turn_id,
        )

    return True
